import type {ArticleCopies} from '../types';

const articles: ArticleCopies = {
  'low-light-houseplants': {
    title: 'Plantas de interior para poca luz: qué significa «tolerante» en lux',
    description: 'Poca luz son unos 500–2.500 lux, no un pasillo sin ventanas. Descubre qué plantas la toleran de verdad, cómo cambian sus cuidados y cuándo añadir una lámpara de cultivo.',
    takeaway: 'Las plantas de poca luz sobreviven a 500–2.500 lux, pero crecen despacio. Por debajo de unos 500 lux incluso las más resistentes necesitan una lámpara de cultivo, y todas piden mucho menos riego que en un lugar luminoso.',
    sections: [
      {heading: 'Pon cifras a la «poca luz»', paragraphs: ['Tus ojos juzgan mal la luz que recibe una planta porque se adaptan constantemente. Un salón que parece agradablemente luminoso suele medir solo 50–500 lux a un par de metros de las ventanas, mientras que para las plantas «poca luz» son 500–2.500 lux. Esa franja es, más o menos, lo que encuentras a 1–2 m de una ventana orientada al norte (en el hemisferio norte) o al fondo de una habitación con una ventana grande al este o al oeste.', 'Por debajo de unos 500 lux, la planta no puede fabricar tantos azúcares como consume y vive de sus reservas. Una planta ZZ o una lengua de suegra pueden parecer iguales durante meses en un rincón oscuro mientras se van agotando poco a poco; por eso «lleva un año bien» no demuestra que un sitio tenga luz suficiente.']},
      {heading: 'La lista corta de las que de verdad la toleran', paragraphs: ['Estas plantas aceptan poca luz y mantienen un follaje sano. Ninguna crece deprisa en esas condiciones, y la mayoría crecería mejor con más luz.'], bullets: ['Planta ZZ (Zamioculcas zamiifolia): sus rizomas, parecidos a patatas, almacenan agua y carbohidratos.', 'Lengua de suegra (Dracaena trifasciata): la fotosíntesis CAM y sus hojas gruesas la hacen muy austera.', 'Aspidistra (Aspidistra elatior): la clásica planta de pasillo oscuro y, según la ASPCA, no tóxica para mascotas.', 'Poto verde (Epipremnum aureum ‘Jade’) y filodendro de hoja corazón (Philodendron hederaceum): cuelgan sin problema a 1.000–2.500 lux.', 'Aglaonema, cultivares verdes: hojas suaves y estampadas que se adaptan a la sombra.', 'Espatifilo (Spathiphyllum): sobrevive con poca luz, pero rara vez florece en ella.']},
      {heading: 'Por qué aguantan y a qué renuncian', paragraphs: ['Las especies tolerantes a la sombra forman «hojas de sombra»: más finas, más anchas y con más clorofila por unidad de superficie, de modo que alcanzan su punto de compensación con menos luz que las plantas de sol. Muchas además almacenan reservas, en rizomas (ZZ, lengua de suegra) o en tallos gruesos, lo que les permite superar largas temporadas de penumbra.', 'El precio es el crecimiento. Cuenta con unas pocas hojas nuevas al año, no con una brotación cada mes. Los cultivares variegados, como el poto ‘Marble Queen’ o la lengua de suegra ‘Laurentii’, tienen menos clorofila en sus zonas claras, así que sufren más en el mismo lugar y a menudo pierden contraste o revierten al verde. Reserva las plantas variegadas para tus rincones más luminosos. Ten en cuenta que la ASPCA clasifica la ZZ, la lengua de suegra, el poto, el filodendro, la aglaonema y el espatifilo como tóxicos para perros y gatos.']},
      {heading: 'Riego y abonado para una planta más lenta', paragraphs: ['Menos luz significa menos fotosíntesis, menos transpiración y una maceta que se seca dos o tres veces más despacio que la misma maceta junto a una ventana luminosa. Aquí es donde mueren la mayoría de las plantas de poca luz: se riegan con el calendario de una «habitación luminosa» y se pudren. Riega el poto y el filodendro solo cuando los 2–5 cm superiores estén secos, lo que puede tardar 2–3 semanas, y espera con la lengua de suegra y la ZZ hasta que el sustrato esté seco en casi toda la maceta, a menudo cada 4–6 semanas en invierno.', 'Usa macetas ajustadas, solo 2–5 cm más anchas que el cepellón; una maceta grande de sustrato mojado en un rincón oscuro es la receta para la podredumbre de raíces. Abona poco, a media dosis unas cuantas veces en primavera y verano, porque una planta lenta aprovecha poco y las sales no utilizadas se acumulan.']},
      {heading: 'Señales de falta de luz y la solución con lámpara', paragraphs: ['Fíjate en entrenudos largos, hojas nuevas claramente más pequeñas que las viejas, tallos muy inclinados hacia la ventana, variegado que se apaga, hojas viejas que amarillean más rápido de lo que salen las nuevas, o ningún crecimiento en toda la primavera y el verano. Cualquiera de estas señales indica que la planta está en déficit.', 'Acércala a la ventana por etapas durante una o dos semanas, o añade luz. Un simple LED blanco de espectro completo con temporizador, encendido 12–14 horas al día y colocado a la distancia que indica el fabricante para plantas de follaje, puede convertir una estantería de 300 lux en una de 5.000 lux y permitirte cultivar casi cualquier cosa allí.']},
    ],
  },
  'vacation-plant-care': {
    title: 'Plantas en vacaciones: cómo prepararlas para una, dos o cuatro semanas',
    description: 'Cómo preparar tus plantas de interior para una semana, quince días o un mes fuera: riego previo, apartarlas de ventanas calurosas, mechas probadas e instrucciones claras.',
    takeaway: 'Riega cada planta según su propia regla 1–2 días antes de irte y aparta las amantes del sol del cristal caliente. Para viajes de más de unas dos semanas, busca a alguien que las cuide en lugar de confiar en un depósito.',
    sections: [
      {heading: 'Adapta el plan a la duración del viaje', paragraphs: ['La mayoría de las plantas de interior sanas, en macetas adecuadas, aguantan una semana solas sin ayuda. El riesgo crece con la duración del viaje, el calor del verano y las macetas pequeñas, que se secan antes. Planifica por separado para las plantas que más tardan en secarse y para las más sedientas.'], bullets: ['Hasta 7 días: riega con normalidad 1–2 días antes de salir; la mayoría no necesita nada más.', '8–14 días: aparta del sol directo las plantas sedientas, agrúpalas y usa una mecha ya probada o una visita de un cuidador a mitad de viaje.', '15 días o más: un cuidador cada 7–10 días, con notas escritas para cada planta.', 'Lengua de suegra, ZZ, aloe y otras suculentas: riega solo si ya están secas. Aguantan 3–4 semanas sin agua con facilidad.']},
      {heading: 'Reduce el consumo de agua antes de irte', paragraphs: ['El consumo de agua de una planta depende de la luz y del calor. Apartar las plantas 1–2 m de las ventanas orientadas al sur o al oeste (al norte o al oeste en el hemisferio sur) reduce su luz y su transpiración sin perjudicarlas durante unas semanas. En verano, bajar las persianas de las ventanas soleadas mantiene la habitación más fresca; en invierno, no dejes nunca que la calefacción baje de 12–15 °C, el mínimo para la monstera, el poto, el espatifilo y el ficus lira.', 'Riega a fondo hasta que salga un 10–20 % por el drenaje y vacía después todos los platos y macetas decorativas. No dejes las plantas en agua «por si acaso»: tras una semana en un plato encharcado, la parte baja del sustrato se queda sin aire y las raíces empiezan a morir. Evita abonar, trasplantar y podar en las dos semanas anteriores a la salida, para no dejar una planta estresada sin nadie que la vigile.']},
      {heading: 'Sistemas caseros de riego que funcionan de verdad', paragraphs: ['La mecha capilar es la opción sencilla más fiable: un cordón de algodón o nailon que va de una jarra de agua al sustrato, introducido unos 5 cm cerca de las raíces, con la jarra a la misma altura que la maceta o un poco más alta. Para un grupo de plantas, colócalas sobre una toalla gruesa y mojada en una bañera o fregadero con 1–2 cm de agua, siempre que la habitación tenga ventana. Las plantas pequeñas que aman la humedad, como los helechos, pueden ir dentro de una tienda holgada de plástico transparente, fuera del sol directo para que no se cuezan.', 'Elijas lo que elijas, pruébalo una semana entera mientras sigues en casa. Las mechas pueden aportar mucho más o mucho menos de lo que esperas según el cordón y el sustrato, y conviene descubrirlo antes del viaje, no después.']},
      {heading: 'Da instrucciones planta por planta', paragraphs: ['«Riega todo el sábado» es la forma en que los cuidadores matan cactus y dejan que los espatifilos se desplomen. Dales instrucciones que puedan comprobar por sí mismos: «mete un dedo hasta el segundo nudillo; si está seco, riega hasta que gotee por abajo y vacía el plato en media hora». Pon una etiqueta de color en cada maceta, por ejemplo verde para comprobar y regar y roja para no regar, y deja una foto de cada planta con su nombre.', 'La función Plant Sitter de PlantPal reúne en un solo lugar instrucciones claras de cuidado de cada planta para la persona que se ocupa de ellas, algo mucho mejor que una nota larga pegada en la nevera. Deja tus datos de contacto, o los de un amigo que entienda de plantas, por si algo no tiene buen aspecto.']},
      {heading: 'La vuelta a casa', paragraphs: ['Resiste la tentación de regarlo todo nada más entrar. Revisa primero cada maceta: puede que el cuidador regara ayer. Un espatifilo mustio suele recuperarse a las pocas horas de un riego a fondo; un cepellón que se ha secado como una piedra y se ha separado de la pared de la maceta se rehidrata mejor sumergiéndolo en agua 20–30 minutos. Devuelve las plantas a su sitio habitual y, si usaste un depósito o una mecha, lava el sustrato con un riego por arriba para eliminar las sales acumuladas.']},
    ],
  },
  'quarantine-new-houseplants': {
    title: 'Cuarentena para plantas nuevas: rutina de inspección de cuatro semanas',
    description: 'Las plantas nuevas son la principal vía de entrada de plagas. Cómo revisarlas al comprar, hacer una cuarentena de 2–4 semanas y qué mirar cada semana con lupa de 10×.',
    takeaway: 'Mantén cada planta nueva 2–4 semanas lejos de tu colección y revísala cada semana con una lupa de 10×. Es tiempo suficiente para que los huevos ocultos se conviertan en plagas visibles.',
    sections: [
      {heading: 'Por qué de dos a cuatro semanas', paragraphs: ['En el momento de la compra, la mayoría de los problemas de plagas son invisibles: los huevos de araña roja son esferas de 0,1 mm en el envés, los de cochinilla algodonosa están dentro de sacos algodonosos en las axilas de las hojas, los de trips se insertan en el tejido foliar y las larvas de los mosquitos del sustrato viven bajo la superficie. Sus ciclos marcan la duración de la cuarentena. La araña roja pasa de huevo a adulto en 7–10 días en habitaciones cálidas, los trips en unas 2–3 semanas y los mosquitos del sustrato en 3–4 semanas. Entre dos y cuatro semanas permiten que al menos una generación se deje ver.', 'Los viveros comerciales también tratan las plantas de forma preventiva, y esos tratamientos pueden mantener las plagas por debajo del nivel visible durante un tiempo después de que la planta salga del vivero. Una planta que parece limpia el primer día todavía no es una planta limpia.']},
      {heading: 'Revisa antes de pagar', paragraphs: ['Dos minutos en la tienda ahorran semanas de tratamiento. Lleva una lupa pequeña o usa el zoom de la cámara del móvil, y mira donde se esconden las plagas, no el lado de la planta que se muestra al cliente.'], bullets: ['Envés de las hojas a lo largo del nervio central: punteado pálido, motas que se mueven o telaraña fina (araña roja).', 'Axilas de las hojas, uniones de los tallos y bajo las vainas foliares: mechones blancos algodonosos (cochinilla algodonosa) o bultos marrones que se desprenden al rascar (cochinilla de escudo).', 'Rayas plateadas con diminutos puntos negros de excrementos en las hojas: trips.', 'Melaza pegajosa, o negrilla (fumagina) en las hojas de debajo.', 'Da unos golpecitos a la maceta: si levantan el vuelo mosquitas negras de la superficie, son mosquitos del sustrato (esciáridos).', 'Si la tienda lo permite, saca el cepellón: las raíces deben estar firmes y claras, no marrones, blandas ni con olor agrio.']},
      {heading: 'Prepara el lugar de cuarentena', paragraphs: ['Usa una habitación aparte si puedes; si no, deja al menos un par de metros entre la recién llegada y tus otras plantas, porque la araña roja se desplaza con las corrientes de aire y camina de una hoja a otra cuando se tocan. El lugar necesita aun así luz y temperatura adecuadas, o confundirás síntomas de estrés con enfermedad. Pon una trampa cromática amarilla en la maceta para vigilar mosquitos del sustrato y trips.', 'Nada más llegar, enjuaga el follaje bajo una ducha templada (con la superficie del sustrato cubierta) y limpia las hojas grandes por ambas caras. Así eliminas buena parte de las plagas móviles y del polvo. Riega y manipula la planta en cuarentena la última de tu rutina, y lávate las manos y las herramientas después.']},
      {heading: 'Revisiones semanales y qué hacer si encuentras algo', paragraphs: ['Una vez por semana, repasa la planta con una lupa de 10×, centrándote en los brotes nuevos, el envés y las axilas de las hojas, y cuenta lo que haya en la trampa adhesiva. Si encuentras algo, identifícalo antes de coger un pulverizador y sigue después el tratamiento específico para esa plaga. Unas pocas cochinillas algodonosas se pueden retirar con un bastoncillo mojado en alcohol isopropílico al 70 % (prueba antes en una hoja); la araña roja, los trips y los mosquitos del sustrato necesitan tratamientos repetidos, ajustados a su ciclo de vida.', 'Reinicia el reloj de la cuarentena desde el último tratamiento: la planta se une a la colección solo después de dos o tres revisiones semanales limpias seguidas. Una planta muy infestada de cochinilla algodonosa o trips suele ser mejor devolverla, o embolsarla y desecharla, que cuidarla junto a una colección sana.']},
      {heading: 'Deja que se asiente antes de cambiar sus cuidados', paragraphs: ['Pasar de un invernadero de vivero a un salón supone una gran caída de luz y humedad, y es normal que caigan algunas hojas, sobre todo en el ficus lira (Ficus lyrata) y el ficus benjamina (Ficus benjamina), que pierden hojas tras casi cualquier cambio. No trasplantes en las primeras 3–4 semanas salvo que la planta esté encharcada o muy enraizada; aprovecha ese tiempo para aprender a qué ritmo se seca su maceta actual. Los sustratos de vivero suelen ser densos y ricos en turba, y se secan más despacio de lo que cabría esperar.', 'Espera también con el abono. La mayoría de las plantas de vivero llegan con suficiente abono de liberación controlada en el sustrato para varias semanas.']},
    ],
  },
  'organize-plants-by-zone': {
    title: 'Organiza tus plantas por zonas: agrúpalas por luz, no por habitación',
    description: 'Agrupar las plantas de interior en zonas según luz, temperatura y velocidad de secado convierte su cuidado en un recorrido semanal rápido. Así se traza el mapa de tu casa.',
    takeaway: 'Define cada zona por su luz medida y por lo rápido que se secan allí las macetas, y revisa una zona cada vez. Una sola habitación puede albergar fácilmente dos o tres zonas muy distintas.',
    sections: [
      {heading: 'Qué convierte un lugar en una zona', paragraphs: ['Los productores de invernadero no organizan las mesas de cultivo según la puerta más cercana; agrupan los cultivos que comparten necesidades de luz, temperatura y riego. Haz lo mismo en casa. Una zona es un lugar donde las condiciones de cultivo son más o menos uniformes. En un mismo salón, un alféizar orientado al sur que marca 30.000 lux a mediodía y una librería en la pared del fondo que marca 300 lux son dos zonas distintas, aunque estén a 4 m.', 'Pon nombre a las zonas por lugar y condición, como «Cocina – alféizar este», «Salón – rincón luminoso» o «Pasillo – poca luz», para que el propio nombre te recuerde, a ti o a quien las cuide, qué pueden esperar allí las plantas.']},
      {heading: 'Traza el mapa de tu casa en una tarde', paragraphs: ['Recorre la casa una vez con un luxómetro y una libreta, y apunta para cada posible ubicación los pocos datos que realmente determinan los cuidados.'], bullets: ['Luz a mediodía a la altura de las hojas, en lux, y la orientación de la ventana.', 'Horas de sol directo sobre las hojas, y si es sol de mañana o de tarde.', 'Fuentes de calor y corrientes de aire: radiadores, salidas del aire acondicionado, hornos, puertas que se abren a menudo.', 'Frío invernal: un alféizar detrás de una cortina cerrada puede bajar de 10 °C por la noche.', 'Humedad: cocinas y baños tienen más que un salón con calefacción.']},
      {heading: 'Asigna cada planta a su zona', paragraphs: ['Con el mapa en la mano, coloca las plantas donde sus necesidades coincidan con las condiciones. Las zonas luminosas (10.000 lux o más, algo de sol directo) convienen al aloe, los cactus, los ficus elástica variegados como el Ficus elastica ‘Tineke’ y el ficus lira. Las zonas medias (2.500–10.000 lux) convienen a la monstera, la mayoría de los filodendros, el poto ‘Marble Queen’ y un espatifilo que quieras ver florecer. Las zonas de poca luz (500–2.500 lux) son para la ZZ, la lengua de suegra y la aspidistra.', 'Dentro de una zona, intenta agrupar las plantas que se secan a un ritmo parecido, para que una sola revisión sirva para varias macetas. Mantén juntas las amantes de la humedad, como las calateas y los helechos, a ser posible cerca de un humidificador; agruparlas les crea un pequeño microclima compartido. Deja las plantas tóxicas para mascotas, como la monstera, el poto y el filodendro, en zonas a las que tu gato no llegue.']},
      {heading: 'Haz un recorrido semanal', paragraphs: ['Coge la regadera y trabaja zona por zona. En cada una, revisa primero las macetas que se secan más rápido: las pequeñas, las de terracota y las que reciben sol directo. Después revisa las lentas y no toques las que sigan húmedas. De paso, echa un vistazo al envés de las hojas en busca de plagas y vacía los platos. Así se atiende bien una colección de 20 plantas en 10–15 minutos.', 'Las zonas cambian con las estaciones. En invierno, las zonas orientadas al sur ganan valor y las orientadas al norte pueden quedarse por debajo de una luz útil, mientras que las macetas en zonas con radiador se secan mucho más deprisa. Cuando una planta tenga que cambiar de zona, muévela por etapas durante 1–2 semanas y cuenta con que su intervalo de riego cambiará.']},
      {heading: 'Mantén el mapa de zonas al día', paragraphs: ['PlantPal te permite clasificar tus plantas en zonas personalizadas que reflejan tu casa, de modo que tu recorrido semanal y el traspaso a un cuidador siguen el mismo mapa. Actualiza la zona de una planta el mismo día que la muevas, porque su antiguo ritmo de cuidados ya no sirve.', 'Vuelve a medir y revisa las zonas dos veces al año, hacia los equinoccios de primavera y otoño, cuando más cambia el ángulo del sol. Los árboles que echan hoja, las cortinas nuevas y las plantas que se hacen sombra unas a otras al crecer cambian una zona más de lo que notas en el día a día.']},
    ],
  },
  'terracotta-vs-plastic-pots': {
    title: 'Macetas de terracota o de plástico: cómo cambia el riego',
    description: 'La terracota sin esmaltar pierde agua por sus paredes y se seca antes que el plástico. Qué plantas van en cada una, por qué salen costras de sales y cómo ajustar el riego.',
    takeaway: 'Usa terracota para las plantas que agradecen secarse, como suculentas, lengua de suegra y ZZ, y macetas de plástico o esmaltadas para las que quieren humedad constante, como el espatifilo y los helechos.',
    sections: [
      {heading: 'Qué hace la pared de la maceta', paragraphs: ['La terracota sin esmaltar es arcilla cocida llena de poros microscópicos. El agua pasa del sustrato a la pared por capilaridad y se evapora por la cara exterior, así que la maceta pierde humedad por toda su superficie lateral, no solo por arriba. Esa evaporación también refresca ligeramente la zona radicular y deja entrar un poco de aire en el borde del cepellón, por eso las raíces suelen pegarse al interior de una maceta de barro. En una habitación cálida y luminosa, una maceta de terracota suele secarse notablemente antes que una de plástico idéntica.', 'El plástico es impermeable, así que el agua solo sale por la superficie y los agujeros de drenaje, y el sustrato se mantiene húmedo de forma uniforme durante más tiempo. La cerámica esmaltada, la terracota pintada o sellada y las macetas de resina o fibra de vidrio se comportan todas como el plástico, tengan el aspecto que tengan.']},
      {heading: 'Dónde se gana su sitio la terracota', paragraphs: ['El barro conviene a las plantas que quieren que el sustrato se seque en profundidad entre riegos: cactus y suculentas, aloe, lengua de suegra (Dracaena trifasciata), ZZ y Hoya. También perdona los excesos a quien tiende a regar de más, porque la maceta juega en contra de una zona radicular empapada. Su peso da estabilidad a plantas altas o pesadas por arriba que volcarían una maceta de plástico.', 'Los inconvenientes son reales. El barro se rompe, y una maceta de 30 cm con sustrato mojado pesa mucho al moverla. Los minerales del agua dura y las sales del abono migran a través de la pared y se secan como una costra blanca por fuera y en el borde; las hojas o tallos que se apoyan en un borde con costra pueden quemarse. Las algas verdes en el exterior son inofensivas. Sumerge una maceta de terracota nueva y totalmente seca en agua unos 30 minutos antes de plantar, o absorberá el agua del sustrato recién puesto y de la planta.']},
      {heading: 'Dónde gana el plástico', paragraphs: ['El plástico es la mejor opción para las plantas que no toleran secarse, como el espatifilo (Spathiphyllum), el helecho de Boston (Nephrolepis exaltata), las calateas y el culantrillo, y para cualquier planta en una ventana caliente y soleada donde el barro exigiría riego cada uno o dos días. También es práctico para cestas colgantes y ejemplares grandes, donde el peso importa, y como maceta interior ligera dentro de un cubremacetas decorativo.', 'El riesgo va en sentido contrario. Con poca luz, o en una maceta mucho más grande que el cepellón, el plástico mantiene el sustrato mojado el tiempo suficiente para que las raíces se asfixien y se pudran. Si eliges plástico, elige un tamaño ajustado, 2–5 cm más ancho que el cepellón, y comprueba la humedad en lugar de regar por calendario.']},
      {heading: 'Cambiar de material sin sorpresas', paragraphs: ['Cambia una sola cosa cada vez. Si pasas una planta a un material nuevo, un tamaño nuevo y un sustrato nuevo a la vez, pierdes toda referencia de cómo se secará. Mantén el tamaño de maceta y el sustrato al cambiar de material, y vuelve a aprender el ritmo a lo largo de dos o tres riegos.'], bullets: ['De plástico a terracota: empieza a comprobar 2–3 días antes de lo que solías.', 'De terracota a plástico: alarga el intervalo y comprueba que los 2–5 cm superiores estén secos antes de regar.', 'Cubremacetas: vacía el agua que quede dentro en los 15–30 minutos siguientes al riego.', 'Reutilizar macetas de barro: frota la costra de sales, déjalas en remojo en 1 parte de vinagre blanco por 3 de agua y acláralas bien.', 'Desinfecta las macetas usadas de cualquier material con 1 parte de lejía doméstica por 9 de agua durante 10 minutos y acláralas después.']},
    ],
  },
  'aroid-potting-mix': {
    title: 'Sustrato para aráceas: una receta base y cómo ajustarla',
    description: 'Las raíces de monstera, filodendro y poto necesitan tanto aire como agua. Una mezcla base 1:1:1 de sustrato, corteza y perlita, y cómo adaptarla a tu maceta y tu luz.',
    takeaway: 'Empieza con aproximadamente 1 parte de sustrato universal, 1 de corteza fina y 1 de perlita o pumita en volumen, y ajústala según lo rápido que se seque la maceta, no añadiendo más ingredientes.',
    sections: [
      {heading: 'Por qué las raíces de las aráceas quieren aire', paragraphs: ['Muchas de las aráceas más populares, como Monstera deliciosa, la mayoría de las especies trepadoras de Philodendron, el poto (Epipremnum aureum), Rhaphidophora y Anthurium, son hemiepífitas o epífitas. En la naturaleza, sus raíces recorren la corteza de los árboles y la hojarasca suelta, donde el aire circula libremente y la lluvia drena en minutos. El oxígeno se difunde unas 10.000 veces más despacio en el agua que en el aire, así que en una mezcla de turba densa y saturada sus raíces gruesas se asfixian en pocos días y entran organismos de podredumbre como Pythium.', 'El objetivo de una mezcla gruesa es dejar una parte importante del volumen de la maceta, a grandes rasgos entre una quinta parte y un tercio, llena de aire incluso justo después de regar. No todas las aráceas lo necesitan: el espatifilo (Spathiphyllum), la aglaonema y la alocasia son terrestres y prefieren una mezcla más fina y húmeda, mientras que la ZZ, también arácea, quiere una arenosa y de secado rápido.']},
      {heading: 'La mezcla base y la función de cada componente', paragraphs: ['Es un punto de partida, no una fórmula. El tamaño de partícula importa más que el nombre de los ingredientes, así que mira el saco y toca la textura.'], bullets: ['1 parte de sustrato de calidad a base de turba o fibra de coco: retiene agua y nutrientes (la turba retiene 10–20 veces su peso seco en agua).', '1 parte de corteza fina de orquídea o de pino, en trozos de 6–20 mm: crea macroporos de aire y se descompone lentamente en 2–3 años.', '1 parte de perlita o pumita: porosidad permanente. La perlita es más ligera y sube a la superficie; la pumita es más pesada, retiene algo de agua en sus poros y se queda en su sitio.', 'Opcional: un puñado de carbón vegetal hortícola o humus de lombriz. Ninguno es imprescindible.']},
      {heading: 'Ajústala a tu planta, tu maceta y tu luz', paragraphs: ['Sube la fracción gruesa (corteza más perlita o pumita) de dos tercios hacia tres cuartos de la mezcla en macetas grandes de más de 25 cm, plantas con luz media o baja, habitaciones frescas, filodendros de hoja aterciopelada como Philodendron gloriosum, anturios, y si riegas con generosidad. Inclínate hacia más sustrato en macetas pequeñas de menos de unos 12 cm, ventanas calurosas y luminosas, potos en cestas colgantes y aráceas terrestres como el espatifilo.', 'La maceta forma parte de la ecuación. Aumenta solo 2–5 cm de diámetro en cada trasplante (5–8 cm en ejemplares grandes), y recuerda que la terracota seca una mezcla gruesa mucho antes que el plástico. En la monstera, colocar un tutor de musgo o de fibra de coco al trasplantar favorece hojas más grandes y más perforadas a medida que la planta trepa.']},
      {heading: 'Mézclala y planta bien', paragraphs: ['Humedece la turba o la fibra de coco antes de mezclar, porque la turba muy seca repele el agua, y moja la perlita para que no levante el polvo fino de sílice; usa mascarilla para cantidades grandes. Combínalo todo en un barreño hasta que quede homogéneo. Al plantar, no aprietes la mezcla. Da unos golpes a la maceta contra la mesa para asentarla y deja que el primer riego termine el trabajo.', 'Retira del cepellón tanta turba vieja y densa de vivero como permitan las raíces. Si un núcleo de turba mojada queda dentro de una mezcla gruesa de drenaje rápido, las dos texturas no intercambian bien el agua: el exterior se seca mientras el núcleo sigue empapado. Riega a fondo hasta que drene un 10–20 %. Usa guantes, porque la savia de estas plantas contiene cristales de oxalato cálcico que irritan la piel y la boca, y todas son tóxicas para perros y gatos.']},
      {heading: 'Interpreta el resultado y mantenlo', paragraphs: ['Una mezcla bien ajustada, con luz indirecta brillante, deja que los 2–5 cm superiores se sequen en más o menos una semana durante la época de crecimiento. Si sigue mojada dos semanas o más, huele agrio o amarillean las hojas bajas, es demasiado densa o la maceta es demasiado grande. Si se seca en dos o tres días y la planta se mustia entre riegos, añade más sustrato la próxima vez.', 'Las mezclas con mucha corteza retienen menos nutrientes, y los microorganismos que descomponen lentamente la corteza consumen parte del nitrógeno, así que abona con regularidad, cada 2–4 semanas, durante el crecimiento activo. A medida que la corteza se descompone, la mezcla se compacta y drena más despacio; trasplanta cada 1–3 años, idealmente en primavera o a principios de verano.']},
    ],
  },
  'self-watering-pots': {
    title: 'Macetas autorriego: cómo funcionan y qué plantas van bien en ellas',
    description: 'Las macetas autorriego suben el agua desde un depósito por capilaridad. Cómo funcionan, qué plantas y sustratos les convienen y cómo evitar raíces encharcadas.',
    takeaway: 'Riega por arriba las primeras 2–4 semanas hasta que las raíces lleguen a la zona de capilaridad, y luego deja que el depósito se vacíe del todo unos días entre recargas para que el aire vuelva a las raíces.',
    sections: [
      {heading: 'Cómo llega el agua del depósito a las raíces', paragraphs: ['Una maceta autorriego es un pequeño sistema de subirrigación. El agua está en un depósito en la base, separado del sustrato por una plataforma o una maceta interior. Una mecha, ya sea un cordón de tela o una columna de sustrato dentro de una cesta perforada, baja hasta el agua y la hace subir por capilaridad, la misma fuerza que hace subir el agua por un papel de cocina. Un orificio de rebose impide que el nivel suba hasta la zona de raíces, y un indicador de flotador muestra cuánto queda.', 'La cámara de aire entre la superficie del agua y el fondo del sustrato es esencial. Si se llena de más el depósito o se obstruye el rebose, la parte baja del sustrato se inunda y las raíces de esa zona mueren. Incluso cuando el sistema funciona como está previsto, el sustrato está más mojado abajo y más seco arriba, y permanece húmedo a todas horas.']},
      {heading: 'Plantas que prosperan y plantas que no', paragraphs: ['La humedad constante es precisamente la razón de ser de estas macetas, así que convienen a las plantas que no toleran secarse y castigan a las que necesitan un periodo seco.'], bullets: ['Buenas candidatas: espatifilo (Spathiphyllum), cinta (Chlorophytum comosum), helecho de Boston, calateas, y albahaca u otras aromáticas en un alféizar soleado.', 'Viables con cuidado: poto, monstera y filodendro con luz brillante, si dejas que el depósito se quede seco varios días entre recargas.', 'Malas candidatas: lengua de suegra, ZZ, aloe, cactus y la mayoría de las suculentas. Necesitan que el sustrato se seque del todo, y la humedad constante pudre sus rizomas y la base de los tallos.']},
      {heading: 'El sustrato importa más que la maceta', paragraphs: ['La capilaridad necesita una red continua de poros finos. Un sustrato universal a base de turba o fibra de coco con un 20–30 % de perlita sube bien el agua sin perder cierto espacio de aire. Las mezclas gruesas para aráceas, con mucha corteza, rompen la cadena capilar y el agua nunca llega a las raíces superiores. Un sustrato denso y fino sin perlita capilariza demasiado y queda casi saturado. Si el fabricante de la maceta indica un sustrato, síguelo.', 'Las plantas recién trasplantadas todavía no han desarrollado raíces hasta la capa húmeda inferior. Riégalas por arriba las primeras 2–4 semanas y solo entonces empieza a llenar el depósito. Un flotador que marca «lleno» te informa del depósito, no del cepellón; mete un dedo en el sustrato para comprobarlo.']},
      {heading: 'Sales, mosquitos y mantenimiento', paragraphs: ['En una maceta normal, el agua sobrante drena y arrastra el exceso de sales. Una maceta autorriego no tiene salida de drenaje, así que los minerales del agua del grifo y del abono se acumulan, sobre todo en la capa superior, donde se evapora el agua. Cada 2–3 meses, riega abundantemente por arriba, vierte el exceso por el rebose y vuelve a llenar con agua sin abono. Abona a entre un cuarto y la mitad de la dosis de la etiqueta, tanto si lo añades al depósito como si lo aplicas por arriba, y nunca eches el concentrado directamente en el depósito.', 'La superficie siempre húmeda atrae a los mosquitos del sustrato; una capa de acolchado de grava de 1–2 cm ayuda. Enjuaga el depósito siempre que huela o crezcan algas, y en cada trasplante.']},
      {heading: 'Usarlas en vacaciones', paragraphs: ['Una maceta autorriego puede mantener una planta durante una o dos semanas de ausencia, pero solo si sabes cuánto dura su depósito en tus condiciones. Llénalo estando en casa y anota cuántos días tarda en vaciarse; la respuesta cambia con la estación, la luz y el tamaño de la planta, así que el intervalo de recarga de la caja es solo orientativo. Haz la prueba en la misma estación que tu viaje y, si el depósito dura menos que tu ausencia, organiza también la visita de un cuidador.']},
    ],
  },
  'monstera-deliciosa-care': {
    title: 'Cuidados de la Monstera deliciosa: luz, sustrato aireado y tutor',
    description: 'Monstera deliciosa: 10.000–20.000 lux, riego cuando se secan los 3–5 cm superiores, mezcla gruesa con corteza, tutor de musgo y qué hace que sus hojas se abran.',
    takeaway: 'La luz impulsa tanto el crecimiento como las perforaciones: dale a la monstera 10.000–20.000 lux de luz indirecta brillante y riega solo cuando los 3–5 cm superiores del sustrato se hayan secado.',
    sections: [
      {heading: 'Una trepadora de selva y lo que eso significa en casa', paragraphs: ['La Monstera deliciosa (Araceae) es originaria de los bosques húmedos del sur de México y Centroamérica. Es una hemiepífita: nace en el suelo del bosque y después trepa por los troncos hacia una luz más intensa, anclándose con gruesas raíces aéreas. Todo lo útil sobre su cultivo se deriva de ese hábito: luz tamizada en lugar de sol abrasador, una zona radicular que respire y algo por donde trepar.', 'Las famosas hendiduras y agujeros (fenestraciones) son un rasgo adulto. Las plantas jóvenes forman hojas enteras con forma de corazón, y la fenestración suele empezar cuando las hojas superan unos 30 cm y la planta recibe luz intensa. Una monstera extendida sin apoyo en un rincón oscuro puede quedarse en fase juvenil durante años. Si quieres hojas perforadas, dale más luz y un tutor, no más abono.']},
      {heading: 'Luz, temperatura y humedad', paragraphs: ['Apunta a 10.000–20.000 lux a la altura de las hojas: a menos de 1 m de una ventana al este o al oeste, o a 1–2 m de una ventana luminosa al sur (al norte en el hemisferio sur). Dos o tres horas de sol de mañana son bienvenidas; el sol fuerte de la tarde a través del cristal decolora y quema una planta no aclimatada, así que acostúmbrala en 1–2 semanas. Por debajo de unos 2.500 lux, el crecimiento se detiene, los tallos se alargan y las hojas nuevas salen más pequeñas y enteras.', 'Mantenla a 18–27 °C con un mínimo de unos 12 °C; las hojas pegadas al cristal frío en invierno desarrollan manchas oscuras de aspecto empapado. Se desenvuelve bien con un 40–60 % de humedad relativa. En el aire de la calefacción invernal, a menudo con un 20–35 % de HR, el humidificador es el único método que ayuda de verdad; pulverizar sube la humedad durante minutos y una bandeja con guijarros apenas se nota.']},
      {heading: 'Riego, sustrato y abonado', paragraphs: ['Riega cuando los 3–5 cm superiores, más o menos entre un cuarto y un tercio de la maceta, estén secos. Después riega a fondo hasta que salga un 10–20 % por los agujeros de drenaje y vacía el cubremacetas en 30 minutos. En una habitación luminosa en verano puede ser cada semana; en invierno, a menudo cada 2–3 semanas. Compruébalo con un dedo o un palillo de madera, no con el calendario.', 'Sus raíces evolucionaron para aferrarse a la corteza al aire libre, así que se asfixian y se pudren en medios densos y encharcados. Una buena mezcla de partida es 1 parte de sustrato de calidad, 1 parte de corteza de pino u orquídea de 6–20 mm y 1 parte de perlita o pumita, en volumen. Trasplanta cada 2–3 años en primavera, solo 2–5 cm más ancha, o 5–8 cm en un ejemplar grande; una maceta demasiado grande mantiene un núcleo frío y mojado que las raíces no pueden aprovechar.', 'De primavera a finales de verano, abona cada 2–4 semanas con un abono para plantas de follaje equilibrado o rico en nitrógeno, a entre media y plena dosis de la etiqueta. Suspéndelo en invierno salvo que la planta esté bajo lámparas de cultivo y siga sacando hojas.']},
      {heading: 'Tutores, poda y multiplicación', paragraphs: ['Un tutor de musgo o de fibra de coco es la mayor mejora para una monstera que madura. Colócalo al trasplantar, ata el tallo principal (nunca los pecíolos) con ataduras blandas y holgadas, y guía las raíces aéreas hacia el tutor. Un tutor húmedo anima a las raíces a agarrarse, y un tallo que trepa produce hojas más grandes y más perforadas que uno extendido. Es normal que algunas raíces aéreas no alcancen el tutor; introdúcelas en la maceta o corta alguna suelta.', 'Para multiplicarla, corta un trozo de tallo con al menos un nudo, idealmente con una raíz aérea y una hoja. Enraízalo en agua o en perlita húmeda a 20–25 °C con luz indirecta brillante; las raíces suelen aparecer en 3–6 semanas. Una hoja con su pecíolo pero sin nudo puede enraizar, pero nunca dará un brote nuevo.']},
      {heading: 'Resumen y problemas habituales', paragraphs: ['Hojas bajas que amarillean con un sustrato que sigue mojado más de una semana indican asfixia radicular y podredumbre: saca la planta de la maceta, corta las raíces marrones y blandas y trasplántala a una mezcla gruesa nueva. Bordes marrones y crujientes con una maceta ligera y seca significan que se seca demasiado entre riegos. Un punteado claro y fino, a veces con telaraña en el envés, es araña roja, que prospera en aire cálido y seco: ducha el follaje y aplica jabón potásico cada 5–7 días durante al menos tres tandas.', 'Todas sus partes contienen rafidios de oxalato cálcico, y masticarlas provoca una irritación dolorosa de boca y garganta. La ASPCA clasifica la monstera como tóxica para perros y gatos, así que mantenla fuera del alcance de mascotas y niños pequeños.'], bullets: ['Luz: 10.000–20.000 lux; el sol de mañana le va bien', 'Riego: cuando los 3–5 cm superiores (entre un cuarto y un tercio de la maceta) estén secos', 'Temperatura: 18–27 °C, mínimo de unos 12 °C', 'Humedad: 40–60 % de HR; humidificador en invierno', 'Sustrato: 1 : 1 : 1 de sustrato, corteza y perlita o pumita', 'Trasplante: cada 2–3 años en primavera, 2–5 cm más ancha']},
    ],
  },
  'pothos-care': {
    title: 'Cuidados del poto: luz, riego y poda para guías frondosas',
    description: 'Consigue un poto frondoso: 2.500–15.000 lux (más en cultivares variegados), riego cuando se seca el cuarto superior del sustrato, poda sobre los nudos y esquejes de un nudo.',
    takeaway: 'El poto sobrevive con poca luz, pero solo se vuelve frondoso por encima de unos 5.000 lux; riega cuando los 3–5 cm superiores estén secos y recorta las guías antes de que se queden peladas por arriba.',
    sections: [
      {heading: 'Una trepadora gigante que vive colgando', paragraphs: ['El poto (Epipremnum aureum, Araceae) procede de Moorea, en la Polinesia Francesa, y se ha naturalizado en todos los trópicos. En la naturaleza trepa por los troncos de los árboles y forma hojas profundamente divididas de más de 60 cm. En casa, colgando de una estantería, nunca recibe los estímulos de trepar y de luz que desencadenan esa forma adulta, así que se queda en su fase juvenil de hoja pequeña.', 'Eso tiene dos consecuencias prácticas. Primero, la luz y el soporte dan forma a la planta mucho más que el abono: una guía conducida por un tutor de musgo con buena luz forma hojas bastante más grandes que una que cuelga hacia abajo. Segundo, los tallos colgantes siguen alargándose por la punta mientras las partes más viejas pierden hojas, así que la poda forma parte del cuidado habitual, no es una operación de rescate.']},
      {heading: 'La luz según el cultivar', paragraphs: ['El poto tolera 1.000–2.500 lux, por eso sobrevive en oficinas, pero a ese nivel crece despacio y se estira con largos tramos pelados entre hojas. Para un crecimiento frondoso, apunta más alto; cuanto más blanco o crema tenga la hoja, menos clorofila tiene y más luz necesita para seguir el ritmo.', 'Las plantas muy variegadas en lugares oscuros sacan hojas nuevas más verdes y crecen muy despacio. En cambio, el sol fuerte de la tarde a través del cristal quema primero el tejido claro. Unas horas de sol de mañana en una ventana al este le van bien a cualquier cultivar. Si no sabes cuánta luz recibe realmente un lugar, un luxómetro como el de PlantPal te da una lectura para compararla con estos rangos.'], bullets: ['‘Jade’ y otras formas totalmente verdes: 2.500–10.000 lux, tolera menos', '‘Golden’ y ‘Neon’: 5.000–15.000 lux', '‘Marble Queen’, ‘Manjula’, ‘Snow Queen’: 10.000–20.000 lux, luz indirecta brillante', 'Todos los cultivares: evita el sol de tarde sin filtrar a través del cristal']},
      {heading: 'Riego, sustrato y temperatura', paragraphs: ['Riega cuando los 3–5 cm superiores, más o menos el cuarto superior de la maceta, se hayan secado; después riega hasta que drene un 10–20 % y vacía el plato. Las cestas colgantes cerca del techo se secan antes porque allí se acumula el aire caliente; revísalas el doble de a menudo que las macetas del suelo. Un poto sediento lo indica claramente: las hojas se ablandan y caen un poco, y recuperan la firmeza a las pocas horas de regar. Una planta que se mustia con la maceta todavía pesada tiene un problema de raíces, no de sed.', 'Cualquier sustrato de interior de calidad con un 20–30 % de perlita añadida sirve; una mezcla de corteza para aráceas también. Trasplanta cada 1–2 años en primavera cuando las raíces rodeen la maceta, solo 2–5 cm más ancha. Abona cada 2–4 semanas de primavera a finales de verano con un abono para plantas de follaje rico en nitrógeno, por ejemplo de proporción 3-1-2, a media dosis.', 'Mantenlo a 18–29 °C y por encima de 12–15 °C. Lo ideal es un 40–60 % de humedad, aunque el poto tolera el aire seco típico del invierno mejor que la mayoría de las aráceas.']},
      {heading: 'Poda y multiplicación por esquejes de un nudo', paragraphs: ['Corta las guías aproximadamente 1 cm por encima de un nudo, el abultamiento donde la hoja se une al tallo. El nudo justo por debajo del corte, y a menudo el siguiente, brotará, convirtiendo una guía larga en dos o tres. Podar unas cuantas guías cada primavera mantiene la parte alta de la maceta frondosa en lugar de calva.', 'Cada nudo lleva un pequeño abultamiento marrón de raíz aérea, y ahí es donde salen las raíces nuevas. Corta los restos de poda en trozos de un solo nudo, cada uno con una hoja y 1–2 cm de tallo, y enraízalos en agua o en perlita húmeda a 20–25 °C. Las raíces aparecen en 2–4 semanas. Cuando alcancen 3–5 cm, planta de tres a cinco esquejes en la maceta madre para rellenar una parte alta despoblada.']},
      {heading: 'Problemas y seguridad para mascotas', paragraphs: ['Una hoja amarilla en la base de una guía vieja es envejecimiento normal. Varias amarilleando a la vez, con el sustrato mojado, significan exceso de riego y podredumbre radicular incipiente: deja que la maceta se seque hasta la mitad de su profundidad y comprueba que las raíces estén blancas y firmes, no marrones y viscosas. Manchas secas y crujientes de color amarillo pardo con la maceta seca indican lo contrario.', 'Los grupos blancos y algodonosos en las axilas de las hojas y a lo largo de los tallos son cochinilla algodonosa. Retírala con un bastoncillo mojado en alcohol isopropílico al 70 % y sigue con jabón potásico cada 7 días hasta que no aparezcan nuevas.', 'El poto contiene cristales insolubles de oxalato cálcico. La ASPCA lo clasifica como tóxico para perros y gatos; masticarlo provoca babeo, dolor de boca y vómitos. Cuelga las guías bien por encima del alcance de las mascotas.']},
    ],
  },
  'snake-plant-care': {
    title: 'Cuidados de la lengua de suegra: CAM, secado profundo y podredumbre',
    description: 'Lengua de suegra: por qué el CAM la hace resistente a la sequía, riego con el 75–100 % del sustrato seco, mezcla arenosa, mínimo de 10 °C y cómo evitar la podredumbre.',
    takeaway: 'Riega la lengua de suegra solo cuando el sustrato esté seco al menos en tres cuartas partes de la maceta, normalmente cada 2–3 semanas en verano y 3–6 en invierno; la podredumbre mata muchas más que la sequía.',
    sections: [
      {heading: 'Hecha para la sequía: CAM y rizomas', paragraphs: ['La lengua de suegra o sansevieria (Dracaena trifasciata, antes Sansevieria trifasciata, Asparagaceae) es originaria del África occidental tropical seca, desde Nigeria hasta el Congo. Usa la fotosíntesis CAM: abre los estomas de noche, almacena el dióxido de carbono como ácido málico y mantiene los estomas cerrados durante el calor del día. Así reduce muchísimo la pérdida de agua en comparación con las plantas de follaje comunes.', 'Además almacena agua en sus hojas gruesas y en sus rizomas subterráneos rastreros. La consecuencia en casa es sencilla: la planta consume muy poca agua, sobre todo con poca luz, y sus raíces están adaptadas a un suelo que se seca por completo. Un sustrato siempre húmedo las priva de oxígeno, y la podredumbre de la base es la principal causa de muerte de la lengua de suegra.']},
      {heading: 'Luz y temperatura', paragraphs: ['Tolera 500–2.500 lux, lo que la convierte en una de las pocas plantas que conserva su aspecto en un pasillo oscuro, pero a ese nivel apenas crece y casi no consume agua. El crecimiento, el grosor de las hojas y los bordes amarillos de la ‘Laurentii’ son mejores a 5.000–20.000 lux. Una vez aclimatada durante 1–2 semanas, acepta varias horas de sol directo.', 'Mantenla a 18–29 °C con un mínimo de unos 10 °C. La combinación peligrosa es frío más humedad: las hojas de una planta enfriada en un sustrato húmedo desarrollan manchas blandas de aspecto empapado que acaban deshaciéndose. La humedad ambiental no es un problema; el aire interior normal, con un 30–50 % de HR, le sienta bien.']},
      {heading: 'Riega según la profundidad, no según la fecha', paragraphs: ['Riega solo cuando el sustrato esté seco en el 75–100 % de la maceta. Clava un palillo de madera hasta el fondo y espera diez minutos; si sale limpio y seco, riega. El peso de la maceta es una comprobación aún más rápida una vez que conoces su peso en seco. Los intervalos típicos son de 2–3 semanas en un lugar luminoso en verano y de 3–6 semanas en invierno.', 'Riega el sustrato alrededor de la roseta, no en su centro; el agua que queda en la base de las hojas inicia la podredumbre. Riega a fondo hasta que drene, o sumerge la maceta por abajo 10–20 minutos, y vacía después el plato por completo.', 'Usa un sustrato para suculentas con un 40–60 % de árido mineral como pumita o perlita. La terracota ayuda a que la mezcla se seque de forma uniforme y aporta peso para equilibrar las hojas altas. La lengua de suegra tolera estar apretada, así que trasplanta solo cada 2–4 años, o cuando los rizomas deformen la maceta de vivero, y solo 2–5 cm más ancha. Abona dos o tres veces entre la primavera y el final del verano a media dosis.']},
      {heading: 'División y esquejes de hoja', paragraphs: ['La división en primavera es el camino más rápido hacia una planta nueva. Saca la planta, corta el rizoma con un cuchillo limpio de forma que cada trozo tenga dos o tres hojas y raíces propias, deja secar los cortes un día, planta en sustrato arenoso seco y espera una semana antes de regar.', 'Los esquejes de hoja también funcionan, pero son lentos. Corta una hoja en secciones de 5–8 cm, fíjate en qué extremo iba hacia abajo, déjalas cicatrizar 1–3 días e introduce el extremo inferior 2 cm en un sustrato apenas húmedo. Las raíces se forman en 4–8 semanas, y los hijuelos en varios meses. Los esquejes de hoja de la ‘Laurentii’ pierden el borde amarillo, porque el variegado solo está en las capas externas del tejido; divídela para conservar la franja.']},
      {heading: 'Diagnóstico de los problemas habituales', paragraphs: ['Casi todos los síntomas de la lengua de suegra tienen que ver con el agua, así que revisa el sustrato antes de actuar. La cochinilla algodonosa, que se esconde en la base de las hojas, es la principal plaga que conviene vigilar. Recuerda que crece despacio, de modo que cualquier solución tarda semanas en notarse en las hojas nuevas.', 'La planta contiene saponinas, no los cristales de oxalato de las aráceas. La ASPCA la clasifica como tóxica para perros y gatos; ingerirla provoca náuseas, vómitos y diarrea.'], bullets: ['Base blanda, translúcida y amarillenta con olor agrio: podredumbre; corta por encima del tejido sano y vuelve a enraizar la hoja', 'Hojas arrugadas y curvadas con el sustrato totalmente seco: sed; riega a fondo', 'Hojas arrugadas con el sustrato mojado: las raíces ya han muerto; sácala de la maceta y revísalas', 'Manchas claras o marrones de quemadura tras pasarla al sol: quemadura solar', 'Hojas lacias que se inclinan: falta de luz, normalmente con exceso de riego']},
    ],
  },
  'zz-plant-care': {
    title: 'Cuidados de la planta ZZ: rizomas, luz flexible y muy poca agua',
    description: 'Planta ZZ: cómo sus rizomas almacenan agua, cuándo regar (sustrato seco al 75–100 %), mínimo de 10 °C, luz de 500 a 15.000 lux y multiplicación lenta por foliolos.',
    takeaway: 'Trata los rizomas como el depósito de agua de la planta: riega la ZZ solo cuando el sustrato esté seco en casi toda la maceta, lo que en invierno puede significar una vez cada 4–6 semanas.',
    sections: [
      {heading: 'Una especialista en sequía del este de África', paragraphs: ['La Zamioculcas zamiifolia (Araceae) crece de forma silvestre en el este de África, desde Kenia hasta Sudáfrica, en lugares con una larga estación seca. Sobrevive a la sequía gracias a rizomas subterráneos parecidos a patatas y a bases de los pecíolos engrosadas que almacenan agua y almidón. En una sequía intensa pierde los foliolos y espera bajo tierra.', 'Lo que parecen tallos ramificados son hojas compuestas que salen directamente del rizoma, cada una con foliolos brillantes. Las nuevas llegan en tandas, a menudo varias a la vez, seguidas de meses de aparente inactividad. Ambos rasgos apuntan en la misma dirección: una ZZ necesita mucha menos agua de lo que sugiere su tamaño, y un periodo tranquilo no es un problema que haya que resolver.']},
      {heading: 'Luz y temperatura', paragraphs: ['Una ZZ sobrevive a 500–1.000 lux en una oficina bajo luces de techo, por eso es tan popular. Pero allí apenas crece. A 5.000–15.000 lux, por ejemplo cerca de una ventana al este o a unos metros de una ventana al sur, saca más tandas y más robustas. El sol de tarde sin filtrar amarillea y quema los foliolos.', 'Con luz débil o que llega de un solo lado, los tallos se inclinan y pueden caerse; gira la maceta un cuarto de vuelta cada mes. Mantenla a 18–27 °C. Tolera hasta unos 10 °C si el sustrato está seco, y la humedad interior normal, del 30–60 %, le va bien.']},
      {heading: 'Regar el rizoma, no las hojas', paragraphs: ['Riega solo cuando el sustrato esté seco en el 75–100 % de la maceta. En verano suele ser cada 2–4 semanas; en invierno, cada 4–6 semanas. Un palillo clavado hasta el fondo dice más que la superficie. Cuando riegues, empapa todo el cepellón hasta que drene y no dejes nunca agua estancada en un cubremacetas.', 'Usa un sustrato para suculentas, o sustrato universal con un 40–50 % de pumita o perlita. Con el tiempo los rizomas engordan lo suficiente para abombar o rajar las macetas de plástico de vivero, que es la señal habitual para trasplantar, cada 2–3 años en primavera. Pásala a una maceta 2–5 cm más ancha y deja la parte superior de los rizomas justo por debajo de la superficie, a la misma profundidad que antes. Abona dos o tres veces entre la primavera y el final del verano con un abono equilibrado a media dosis.']},
      {heading: 'Multiplicación: hace falta paciencia', paragraphs: ['La división es lo más rápido. Al trasplantar, separa o corta el grupo de rizomas en trozos, cada uno con al menos un tallo y raíces propias, y plántalos en sustrato seco. Espera más o menos una semana antes del primer riego para que los tejidos dañados cicatricen.', 'Los foliolos sueltos también enraízan. Introduce la base de un foliolo 1 cm en un sustrato arenoso húmedo o ponlo en agua; forma raíces y un pequeño rizoma en 1–3 meses, pero el primer tallo nuevo suele tardar 6–12 meses. Los esquejes de tallo completo enraízan antes y merece la pena probarlos con cualquier tallo que se rompa al trasplantar.']},
      {heading: 'Señales de alarma y seguridad', paragraphs: ['El único riesgo serio para una ZZ es el exceso de riego, y se manifiesta de forma previsible. Varios tallos amarilleando a la vez, con un sustrato que ha seguido mojado, significan que los rizomas se están pudriendo: saca la planta, corta hasta llegar a tejido firme y claro, deja secar los cortes y vuelve a plantar en sustrato seco. Que amarillee un solo tallo viejo mientras el resto sigue brillante es renovación normal. Una caída intensa de foliolos con la maceta completamente seca indica sequía o frío; tallos inclinados y alargados indican falta de luz.', 'La ZZ contiene cristales de oxalato cálcico. La ASPCA la clasifica como tóxica para perros y gatos, y su savia puede irritar la piel, así que usa guantes al dividirla. Un recordatorio de PlantPal funciona bien aquí, ya que la mayoría de las revisiones terminan decidiendo no regar hoy.'], bullets: ['Luz: tolera 500–1.000 lux; crece mejor a 5.000–15.000 lux', 'Riego: cuando el 75–100 % del sustrato esté seco; cada 4–6 semanas en invierno', 'Temperatura: 18–27 °C, mínimo de unos 10 °C con el sustrato seco', 'Sustrato: sustrato universal con un 40–50 % de pumita o perlita', 'Trasplante: cada 2–3 años, cuando los rizomas llenen la maceta']},
    ],
  },
  'peace-lily-care': {
    title: 'Cuidados del espatifilo: humedad constante, agua limpia y más flores',
    description: 'Espatifilo: riega cuando se seque el primer 1–2 cm, 5.000–15.000 lux para florecer, más de 15 °C y cómo corregir las puntas marrones por sales, flúor o marchitez.',
    takeaway: 'Riega el espatifilo cuando el primer 1–2 cm de sustrato esté seco, antes de que se mustie; cada desplome espectacular le cuesta puntas de hojas y hojas viejas.',
    sections: [
      {heading: 'Una planta de suelos de selva húmedos', paragraphs: ['Los espatifilos (Spathiphyllum wallisii y sus híbridos, Araceae) crecen en el sotobosque sombrío de las selvas tropicales americanas, de Colombia a Venezuela, a menudo en suelos siempre húmedos junto a arroyos. Sus raíces son más finas y menos tolerantes a la sequía que las de aráceas trepadoras como la monstera, y la planta no tiene ningún rizoma de reserva de agua en el que apoyarse.', 'Eso explica su perfil de cuidados: una humedad más constante que la mayoría de las plantas de interior, hojas tolerantes a la sombra y una necesidad real de más luz si quieres flores. También explica por qué un espatifilo se desploma de forma tan teatral cuando se seca. Sus hojas finas pierden turgencia muy deprisa.']},
      {heading: 'Luz para las hojas frente a luz para las flores', paragraphs: ['El follaje se mantiene sano a 2.500–5.000 lux, pero la floración necesita 5.000–15.000 lux, más o menos a 1–2 m de una ventana al este o más atrás de una al sur. El sol directo a través del cristal decolora las hojas hasta un blanco amarillento y quema zonas.', 'La «flor» blanca es una espata, una bráctea modificada que envuelve el espádice, donde están las diminutas flores verdaderas. Se vuelve verde al envejecer; corta el tallo por la base cuando se ponga marrón. Muchas plantas de vivero se hacen florecer en fecha con un regulador del crecimiento, así que es normal una floración completa en la tienda seguida de meses sin flores en casa. Lo que las hace volver es una buena luz, no más abono.', 'Mantenlo a 18–27 °C con un mínimo de unos 15 °C; las corrientes frías y las temperaturas cercanas a 10 °C provocan manchas oscuras de daño. Una humedad del 40–60 % mantiene las puntas más limpias.']},
      {heading: 'Riego: adelántate a la marchitez', paragraphs: ['Riega cuando el primer 1–2 cm de sustrato esté seco, lo que en una habitación cálida puede ser cada 4–7 días. Levanta la maceta para aprender cuánto pesa cuando necesita agua. Un espatifilo mustio suele recuperarse a las pocas horas de regarlo, pero cada desplome mata puntas de raíces y bordes de hojas, lo que se nota días después en hojas bajas amarillas y puntas marrones.', 'Si la turba se ha secado y se ha separado de la pared de la maceta, el agua pasa de largo; sumérgela por abajo 10–30 minutos hasta que la superficie se oscurezca y deja escurrir. Una planta que se mustia con el sustrato aún mojado tiene las raíces dañadas, y más agua la empeora.', 'Usa un sustrato a base de turba o fibra de coco con un 20–30 % de perlita. Los espatifilos crecen deprisa y pronto llenan la maceta de raíces, secándose en pocos días; trasplanta cada 1–2 años en primavera, 2–5 cm más ancha, y divide al mismo tiempo las matas apretadas. Cada división necesita su propia corona, raíces y al menos tres hojas.']},
      {heading: 'Puntas marrones: sales, flúor y abonado', paragraphs: ['El espatifilo es sensible a las sales disueltas y al flúor, y ambos se manifiestan como puntas de hoja marrones. El abono es la causa más frecuente. Abona cada 4–6 semanas de primavera a finales de verano a media dosis de la etiqueta; más abono no da más flores.', 'Repasa esta lista cuando las puntas se pongan marrones, y recuerda que el tejido dañado no volverá a ponerse verde. Valora el progreso en las hojas nuevas.'], bullets: ['Marchitez entre riegos: riega al llegar a 1–2 cm secos, no al desplome', 'Acumulación de sales: costra blanca en la maceta o en la superficie del sustrato; lava el sustrato con 2–3 veces el volumen de la maceta en agua', 'Agua del grifo fluorada o descalcificada: cambia a agua de lluvia, destilada o de ósmosis inversa', 'Exceso de abono: baja a media dosis cada 4–6 semanas', 'Aire invernal seco: mantén la HR por encima del 40 % con un humidificador']},
      {heading: 'Plagas y seguridad para mascotas', paragraphs: ['El sustrato siempre húmedo convierte al espatifilo en el favorito de los mosquitos del sustrato. Las trampas cromáticas amarillas revelan el problema, y un riego con BTi (Bacillus thuringiensis israelensis) cada 5–7 días durante 3–4 ciclos elimina las larvas sin tener que dejar secar la planta. Con aire seco, revisa el envés de las hojas en busca de araña roja; en la base de las hojas, busca cochinilla algodonosa.', 'El espatifilo no es un lirio verdadero y no causa la insuficiencia renal que provocan las especies de Lilium en los gatos. Sí contiene cristales de oxalato cálcico, y la ASPCA lo clasifica como tóxico para perros y gatos; masticarlo provoca dolor de boca, babeo y dificultad para tragar.']},
    ],
  },
  'rubber-plant-care': {
    title: 'Cuidados del ficus elástica: luz intensa, estabilidad y ramificación',
    description: 'Ficus elastica: 10.000–20.000 lux, riego con los 3–5 cm superiores secos, siempre por encima de 12 °C, poda o incisión para ramificar y causas de la caída de hojas.',
    takeaway: 'El ficus elástica premia la constancia: al menos 10.000 lux de luz intensa, riego cuando el cuarto superior del sustrato esté seco y nada de cambios bruscos, corrientes ni noches por debajo de 12 °C.',
    sections: [
      {heading: 'Una higuera tropical en el salón', paragraphs: ['El Ficus elastica (Moraceae) es originario de los bosques monzónicos del noreste de la India, pasando por Myanmar, hasta Malasia e Indonesia. En la naturaleza se convierte en un árbol de 30 m, que a menudo empieza su vida sobre otro árbol y deja caer raíces aéreas. Sus hojas gruesas y cerosas están hechas para la luz intensa del dosel, y el látex lechoso que le da nombre sella las heridas.', 'En casa tiende a crecer con un único tallo recto, porque la yema terminal inhibe las yemas de debajo. Como la mayoría de los ficus, reacciona a los cambios bruscos soltando hojas. De ahí salen tres reglas: dale luz intensa, mantén las condiciones estables y pódalo si quieres una forma más poblada.']},
      {heading: 'Luz, temperatura y estabilidad', paragraphs: ['Apunta a 10.000–20.000 lux: cerca de una ventana al este o al oeste, o a 1–2 m de una al sur. Una vez aclimatado durante 1–2 semanas, soporta unas horas de sol de mañana o de invierno. Los cultivares variegados ‘Tineke’ y ‘Ruby’ necesitan la parte alta de ese rango para conservar sus tonos crema y rosa; con poca luz, sus hojas nuevas salen más verdes. Por debajo de unos 2.500 lux, cualquier ficus elástica se estira, forma hojas más pequeñas y pierde las más bajas.', 'Mantenlo a 18–29 °C y por encima de 12 °C. Las corrientes frías de una puerta abierta, del aire acondicionado o de una ventana en invierno provocan una caída repentina de hojas, igual que el golpe de calor de un radiador. La humedad interior normal, del 40–60 %, le va bien. Elige su sitio con cuidado y déjalo allí; una planta que pierde unas hojas tras un cambio de lugar necesita tiempo, no un nuevo plan de riego.']},
      {heading: 'Riego, sustrato y abonado', paragraphs: ['Riega cuando los 3–5 cm superiores, más o menos entre un cuarto y un tercio de la maceta, estén secos. En una maceta grande de suelo, clava un palillo 10–15 cm, porque la superficie se seca mucho antes que el interior. Riega hasta que drene un 10–20 % y vacía el plato en 30 minutos. Limpia las hojas con un paño húmedo cada uno o dos meses; el polvo reduce la luz que reciben, y los abrillantadores foliares obstruyen la superficie.', 'Usa un sustrato de calidad con un 25–30 % de perlita o corteza de pino fina, en una maceta pesada que no vuelque cuando la planta crezca. Trasplanta cada 2–3 años en primavera, 2–5 cm más ancha, o 5–8 cm en un ejemplar grande. Cuando ya esté en una maceta de más de 30 cm, sustituye en su lugar los 3–5 cm superiores de sustrato cada primavera. Abona cada 2–4 semanas de primavera a finales de verano con un abono para plantas de follaje rico en nitrógeno, por ejemplo de proporción 3-1-2.']},
      {heading: 'Poda, incisiones y multiplicación', paragraphs: ['Cortar la punta aproximadamente 1 cm por encima de un nudo en primavera quita el freno hormonal a las yemas de debajo, y de una a tres de ellas brotarán en ramas. La incisión, un corte superficial de 2–3 mm en el tallo justo por encima de una yema latente, interrumpe esa señal localmente y puede despertar una sola yema sin eliminar la punta. Usa guantes: el látex irrita la piel y los ojos. Un papel de cocina húmedo apretado sobre el corte detiene el sangrado.', 'Los esquejes apicales de 10–15 cm con dos o tres hojas enraízan en agua o en perlita húmeda a 22–27 °C en 3–6 semanas. Para tallos gruesos, el acodo aéreo funciona mejor: haz una herida en el tallo, envuélvela en esfagno húmedo y plástico, y las raíces se formarán en 4–8 semanas.']},
      {heading: 'Diagnóstico de la caída de hojas y otros problemas', paragraphs: ['La caída de hojas es el síntoma que los propietarios notan primero, y el patrón revela la causa. Fíjate en qué hojas caen, si están verdes o amarillas y lo mojado que está el sustrato, y cambia una sola cosa cada vez. Una planta que ha perdido hojas desde la base hacia arriba no las volverá a sacar ahí; la poda es la forma de conseguir brotes nuevos más abajo.', 'La ASPCA clasifica el ficus elástica como tóxico para perros y gatos. El látex irrita la piel y los ojos, y masticarlo provoca vómitos y babeo, así que mantén la planta y sus restos de poda lejos de mascotas y niños.'], bullets: ['Hojas verdes y sanas que caen de repente: choque por frío, una corriente o un cambio de lugar', 'Hojas bajas que amarillean y luego caen, con el sustrato mojado: exceso de riego y daño radicular', 'Hojas bajas que se curvan y caen con la maceta seca: falta de riego', 'Bultos marrones en tallos y nervios centrales, melaza pegajosa: cochinilla; trátala con aceite hortícola', 'Pequeños bultos corchosos en el envés: edema por riego irregular en condiciones frescas']},
    ],
  },
  'common-houseplant-fertilizers': {
    title: 'Abonos para plantas de interior: líquidos, gránulos y orgánicos',
    description: 'Cómo difieren concentrados líquidos, dosificadores listos para usar, gránulos de liberación controlada y abonos orgánicos en aporte, riesgo de sales y esfuerzo.',
    takeaway: 'Elige un formato de abonado y aplícalo con constancia: un líquido equilibrado a dosis de etiqueta cada 2–4 semanas durante el crecimiento activo, o un producto de liberación controlada; nunca ambos a dosis completa.',
    sections: [
      {heading: 'Lee el análisis antes que la marca', paragraphs: ['Toda etiqueta de abono lleva tres cifras: el porcentaje en peso de nitrógeno (N), fosfato asimilable (P₂O₅) y potasa soluble (K₂O). Para obtener los valores elementales, multiplica el fosfato por 0,436 y la potasa por 0,83, de modo que un producto 2-2-2 aporta en realidad cerca de un 2 % de N, un 0,9 % de P y un 1,7 % de K.', 'La proporción dice más que el tamaño de las cifras. Las plantas de follaje construyen sus hojas con nitrógeno, así que proporciones como 3-1-2 van bien a la monstera, el poto y el filodendro; los abonos equilibrados 1-1-1 o 2-2-2 funcionan para colecciones mixtas. Un polvo de alta concentración y un líquido de baja concentración pueden aportar los mismos nutrientes una vez diluidos según las instrucciones: lo que llega a las raíces es la solución de trabajo, no lo que aparece en letra grande en la parte delantera.']},
      {heading: 'Abonos líquidos: rápidos, flexibles y fáciles de suspender', paragraphs: ['Los líquidos aportan nutrientes ya disueltos, así que las raíces pueden absorberlos en pocas horas. Eso los convierte en el formato más controlable en interior: tú decides cada dosis y puedes simplemente parar cuando el crecimiento se frena en otoño. Dos ejemplos conocidos de Estados Unidos ilustran la variedad. Según el fabricante, Miracle-Gro Indoor Plant Food es un líquido 1-1-1 con dosificador de bomba, mientras que Espoma Organic Indoor! es un concentrado líquido 2-2-2 que debe diluirse antes de usarlo.', 'Los hábitos de medida difieren entre esos formatos, así que nunca traslades un número de pulsaciones o una medida de tapón de un producto a otro. Un abono bien preparado para la mayoría de las plantas de follaje queda en torno a 0,8–1,5 mS/cm de conductividad eléctrica (CE); muchos cultivadores abonan a media dosis cada riego o cada dos riegos en lugar de a dosis completa una vez al mes, lo que mantiene más estables las sales en la zona radicular.']},
      {heading: 'Gránulos de liberación controlada: la temperatura marca el ritmo', paragraphs: ['Los gránulos recubiertos, como Osmocote, liberan nutrientes a medida que el agua se difunde a través de una cubierta de resina, y el ritmo depende sobre todo de la temperatura. Las duraciones de la etiqueta, de 3–4, 6 u 8–9 meses, están calculadas a unos 21 °C; en un alféizar cálido la liberación es más rápida y en una habitación fresca en invierno se ralentiza.', 'La comodidad es real, pero los gránulos no se pueden apagar. Si una planta se estanca o sus raíces se dañan, los gránulos siguen liberando. Anota la fecha y la dosis que aplicaste, y no superpongas un programa de abono líquido a dosis completa: es la vía más habitual hacia las quemaduras por abono en colecciones por lo demás sanas.']},
      {heading: 'Abonos orgánicos: los microorganismos hacen el trabajo', paragraphs: ['Gran parte del nitrógeno de los abonos orgánicos está ligado a proteínas y otros compuestos que los microorganismos del suelo deben convertir en amonio y nitrato antes de que las raíces puedan absorberlo. Los sustratos sin tierra a base de turba o fibra de coco en una habitación fresca albergan mucha menos actividad de ese tipo que la tierra de jardín, así que en interior los abonos orgánicos suelen actuar de forma más suave y lenta.', 'Orgánico no significa sin sales. Los abonos orgánicos disueltos también elevan la CE, y una sobredosis también daña las puntas de las raíces. Algunos además huelen y dejan películas en la superficie de la maceta; una capa superior húmeda y rica en materia orgánica favorece a los mosquitos del sustrato, así que deja secar los 2–5 cm superiores entre riegos cuando la especie lo permita.']},
      {heading: 'Elegir el formato según tus plantas y la estación', paragraphs: ['Abona solo cuando la planta esté creciendo activamente, más o menos de primavera a finales de verano en viviendas de clima templado, y reduce o suspende en invierno salvo que esté bajo lámparas de cultivo. Ningún abono compensa una luz escasa o unas raíces podridas; soluciona eso primero. Los recordatorios de PlantPal sirven aquí sobre todo para espaciar los abonados con regularidad, no para abonar más a menudo.'], bullets: ['Colección mixta, cultivador muy pendiente: líquido equilibrado a media dosis cada 1–2 semanas durante el crecimiento', 'Casa con poco tiempo o con cuidador: una aplicación de liberación controlada en primavera, sin líquido extra', 'Especies sensibles a las sales (cinta, espatifilo, Dracaena): líquido a baja concentración más un lavado del sustrato cada 2–3 meses', 'Recién trasplantada a un sustrato con abono incorporado: nada de abono adicional durante al menos 6–8 semanas', 'Suculentas y cactus: abono diluido 2–3 veces, solo en verano']},
    ],
  },
  'miracle-gro-indoor-plant-food': {
    title: 'Miracle-Gro Indoor Plant Food: guía del dosificador 1-1-1',
    description: 'Qué significa en la práctica el análisis 1-1-1 de Miracle-Gro Indoor Plant Food, cómo encajar el dosificador en tu programa de abonado y cuándo no usarlo.',
    takeaway: 'Trata el dosificador 1-1-1 como un abono suave y equilibrado: aplícalo sobre un sustrato ya húmedo durante el crecimiento activo, sigue la etiqueta de tu país y no lo uses con la poca luz del invierno.',
    sections: [
      {heading: 'Qué dice el fabricante sobre el producto', paragraphs: ['Según la página del fabricante en Estados Unidos, Miracle-Gro Indoor Plant Food es un abono líquido con un análisis 1-1-1, vendido en un frasco con dosificador de bomba y pensado para plantas de interior. La página describe tanto aplicar las pulsaciones directamente sobre el sustrato como diluirlas en una regadera. Este resumen se basa en esa información publicada y en principios hortícolas generales; no es una prueba práctica del producto.', 'Miracle-Gro vende muchos otros abonos, incluidos polvos hidrosolubles con análisis mucho más altos e instrucciones totalmente distintas. Las formulaciones y etiquetas también varían según el país. Comprueba que el nombre y las cifras de tu frasco coinciden, y sigue la etiqueta de tu país para la dosis y la frecuencia.']},
      {heading: 'Qué significa 1-1-1 una vez en la maceta', paragraphs: ['Un análisis 1-1-1 significa un 1 % de nitrógeno, un 1 % de fosfato (cerca de un 0,44 % de fósforo elemental) y un 1 % de potasa (cerca de un 0,83 % de potasio) en peso. Es un producto equilibrado y de baja concentración. La baja concentración es una ventaja práctica para el aficionado: un pequeño error al medir cambia la dosis mucho menos que con un polvo concentrado.', 'La proporción equilibrada aporta proporcionalmente más fósforo del que usan la mayoría de las plantas de follaje; las aráceas de hoja y los helechos suelen responder mejor a abonos ricos en nitrógeno, en torno a 3-1-2. Para un alféizar mixto de plantas de follaje y de flor, un abono equilibrado es un compromiso razonable. El exceso de fósforo no es dañino de inmediato, pero se suma a las sales que se acumulan en el sustrato.']},
      {heading: 'Encajar el dosificador en un programa de abonado', paragraphs: ['El dosificador está pensado para la comodidad, y es precisamente con la comodidad cuando las rutinas se descontrolan. Vincúlalo a un calendario definido en lugar de usarlo cada vez que el frasco te llame la atención.'], bullets: ['Abona solo durante el crecimiento activo, más o menos de primavera a finales de verano, con el intervalo que indique tu etiqueta', 'Riega primero si el sustrato está seco: los nutrientes aplicados sobre turba o fibra de coco totalmente secas se concentran en las pocas raíces que están húmedas', 'Usa siempre el mismo método de aplicación; no alternes pulsaciones directas y dilución en regadera sin llevar la cuenta del total', 'Tras trasplantar a un sustrato con abono incorporado, espera al menos 6–8 semanas antes de empezar', 'Bajo lámparas de cultivo en invierno, continúa en el extremo bajo de la dosis de la etiqueta']},
      {heading: 'Sales, CE y calidad del agua', paragraphs: ['Cada abonado añade sales solubles, y las macetas de interior rara vez reciben un lavado tipo lluvia suficiente para eliminarlas. El agua dura del grifo añade además carbonato cálcico, que aparece como una costra blanca en el borde y la superficie. La acumulación de sales eleva la presión osmótica alrededor de las raíces, dificulta la absorción de agua y provoca puntas y bordes de hojas marrones.', 'Cada 2–3 meses, o cuando aparezca una costra, lava el sustrato: haz pasar por la maceta 2–3 veces su volumen en agua limpia, siempre que el drenaje y las raíces estén bien. No uses nunca agua de un descalcificador de sal, que añade sodio. Las especies sensibles a las sales y al flúor, como la cinta (Chlorophytum comosum), el espatifilo y la Dracaena, agradecen el extremo bajo del rango de la etiqueta.']},
      {heading: 'Cuándo no usarlo', paragraphs: ['El abono no puede arreglar un problema causado por la luz, el agua o las raíces, y abonar una planta estresada suele añadir daño. Deja el frasco cerrado cuando una planta esté mustia con el sustrato mojado, cuando las raíces estén blandas o marrones, cuando los esquejes aún no tengan raíces funcionales o cuando las suculentas y la lengua de suegra estén en reposo invernal. Si los brotes nuevos salen pálidos y pequeños en una habitación oscura, acerca la planta a una luz más intensa antes de recurrir al abono; más abono con poca luz significa sobre todo más sal en la maceta.']},
    ],
  },
  'espoma-indoor-plant-food': {
    title: 'Abono Espoma Organic Indoor!: cómo usar bien un concentrado 2-2-2',
    description: 'Espoma Organic Indoor! 2-2-2 según su etiqueta: cómo se comporta el nitrógeno orgánico en el sustrato, cómo medir las diluciones y cuándo no abonar.',
    takeaway: 'Diluye siempre el concentrado exactamente como indique la etiqueta de tu país, abona solo plantas en crecimiento activo y recuerda que los abonos orgánicos también aportan sales.',
    sections: [
      {heading: 'Qué afirma Espoma sobre el producto', paragraphs: ['Según el fabricante, Espoma Organic Indoor! Houseplant Food es un concentrado líquido con un análisis 2-2-2, comercializado como opción orgánica, que debe diluirse en agua antes de aplicarlo al sustrato. Este artículo resume esa información publicada y añade contexto hortícola general; no es una prueba práctica del producto ni una recomendación para cualquier planta.', 'Las etiquetas se revisan y pueden variar entre mercados. Antes del primer uso, lee la dosis de dilución, el intervalo de aplicación y las indicaciones de conservación de tu propio frasco, y sigue la etiqueta de tu país siempre que difiera de lo que se dice aquí.']},
      {heading: 'Cómo se comporta el nitrógeno orgánico en una maceta', paragraphs: ['Gran parte del nitrógeno de los abonos orgánicos llega en formas que los microorganismos deben descomponer en amonio y nitrato antes de que las raíces puedan absorberlo. La tierra de jardín está repleta de esos organismos; un sustrato sin tierra de turba o fibra de coco a 18–22 °C alberga muchos menos. El resultado práctico es una respuesta más suave y lenta que con un abono mineral totalmente soluble.', 'Esa suavidad es útil para principiantes, pero tienta a añadir más cuando no se ve nada en una semana. Valora los resultados a lo largo de 4–6 semanas de crecimiento nuevo, no en días. El color de las hojas y la longitud de los entrenudos de los brotes nuevos son mejores indicadores que las hojas viejas, que rara vez cambian.']},
      {heading: 'En la dilución se gana o se pierde la precisión', paragraphs: ['Un concentrado 2-2-2 contiene el doble de porcentaje de nutrientes por unidad de peso que un producto 1-1-1, pero la concentración de la etiqueta no dice nada de la fuerza de trabajo; solo tu dilución la determina. Mide con una cuchara medidora de cocina o una jeringa oral reservadas para las plantas, nunca a ojo ni echando a chorro desde el frasco.', 'Agita antes el frasco, porque los concentrados orgánicos pueden sedimentar. Prepara solo lo que vayas a usar ese día y echa las sobras en los arriates del exterior en lugar de guardar abono diluido, que puede fermentar y oler. Riega ligeramente primero si el sustrato está seco, aplica después el abono diluido hasta que salga un 10–20 % por los agujeros de drenaje y vacía el plato en 15–30 minutos.']},
      {heading: 'Organizar una temporada en torno a él', paragraphs: ['Un programa sencillo para una colección mixta de plantas de follaje tropicales sería así, ajustado a tu etiqueta.'], bullets: ['Principios de primavera, cuando aparecen hojas nuevas: empieza a media dosis de la etiqueta en el primer abonado', 'De finales de primavera a finales de verano: dosis de la etiqueta al intervalo indicado, normalmente cada 2–4 semanas', 'Principios de otoño: alarga el intervalo a medida que se frena el crecimiento', 'Invierno con poca luz: suspende; retómalo solo en plantas bajo lámparas de cultivo', 'Cada 2–3 meses: lava el sustrato con 2–3 volúmenes de maceta de agua limpia para eliminar las sales acumuladas']},
      {heading: 'Cuándo esperar', paragraphs: ['No abones cuando las raíces estén encharcadas o pudriéndose, cuando una planta se acabe de trasplantar a un sustrato que ya contiene abono, ni en esquejes sin raíces. Los líquidos orgánicos dejan materia orgánica disuelta en la superficie del sustrato, y una superficie orgánica siempre húmeda es justo donde prosperan las larvas de los mosquitos del sustrato, así que deja secar los 2–5 cm superiores entre riegos en las especies que lo toleran.', 'Orgánico no significa apto para ingerir. Guarda el concentrado en su envase original, lejos del calor, los niños y las mascotas, y mantén los utensilios de medida de las plantas separados de los de cocina.']},
    ],
  },
  'miracle-gro-indoor-potting-mix': {
    title: 'Sustrato Miracle-Gro Indoor Potting Mix: qué implica su etiqueta',
    description: 'Miracle-Gro Indoor Potting Mix según su etiqueta: mezcla de fibra de coco sin compost ni corteza, con abono inicial, y cómo cambia tu rutina de cuidados.',
    takeaway: 'Trata el abono incorporado como tu primer programa de abonado: no añadas abono extra durante al menos 2–3 meses tras plantar y observa los brotes nuevos antes de retomarlo.',
    sections: [
      {heading: 'Qué describe el fabricante', paragraphs: ['En su página de producto de Estados Unidos, Miracle-Gro describe Indoor Potting Mix como una mezcla para plantas de interior en maceta que contiene fibra de coco, no contiene compost ni corteza, nutre hasta 6 meses y es menos propensa a los mosquitos del sustrato. Son afirmaciones del fabricante; este resumen explica lo que significan en la práctica y no se basa en pruebas propias.', 'La marca vende otros sustratos, y las formulaciones envasadas difieren según el país y cambian con el tiempo. Comprueba los ingredientes y la indicación de abonado de tu propio saco y sigue la etiqueta de tu país.']},
      {heading: 'Cómo se comporta un sustrato a base de fibra de coco', paragraphs: ['La fibra de coco es la médula y la fibra procesadas de la cáscara del coco. Suele tener un pH de 5,5–6,8, retiene mucha agua manteniendo cierto espacio de aire, y la fibra de buena calidad se lava y se tampona con calcio para que no bloquee el calcio y el magnesio. Como la turba, cuesta rehidratarla si se seca por completo; si el sustrato se separa de la pared de la maceta, sumérgela por abajo 10–30 minutos hasta que la superficie se oscurezca y deja escurrir bien.', 'Un sustrato envasado fino y uniforme retiene la humedad. En una maceta poco profunda mantiene una capa freática colgada saturada en la base, que la grava no elimina. Para la mayoría de las plantas de follaje, riega cuando los 2–5 cm superiores estén secos. Para aráceas trepadoras como la Monstera deliciosa, muchos cultivadores la aligeran con aproximadamente 1 parte de sustrato, 1 de corteza fina y 1 de perlita o pumita.']},
      {heading: 'El abono incorporado y tu calendario de abonado', paragraphs: ['El fabricante dice que el sustrato nutre hasta 6 meses. Tómalo como límite máximo: la liberación de nutrientes depende de la temperatura, de la frecuencia de riego y del vigor de la planta, así que un poto cálido, luminoso y de crecimiento rápido lo agota antes que una ZZ lenta en una habitación fresca.', 'No añadas gránulos de liberación controlada ni abono líquido a dosis completa a un sustrato nuevo ya abonado; eso duplica la carga de sales alrededor de unas raíces nuevas que aún se están estableciendo. Una pauta sensata es no abonar nada los primeros 2–3 meses, empezar después con un líquido a media dosis si las hojas nuevas salen más pequeñas o más pálidas, y pasar a tu programa normal hacia el 4.º–6.º mes.']},
      {heading: 'Mosquitos del sustrato: por qué ayuda la fórmula y qué sigue importando', paragraphs: ['Las larvas de los mosquitos del sustrato (Bradysia spp.) viven en los 5 cm superiores de los medios orgánicos húmedos y se alimentan de hongos y materia en descomposición. Eliminar el compost y la corteza les quita parte de su alimento preferido, lo que respalda la afirmación del fabricante. Aun así, la fibra de coco sigue siendo orgánica, y cualquier sustrato que se mantenga siempre mojado puede albergar mosquitos.', 'La prevención depende sobre todo de la humedad en la superficie. Deja secar los 2–5 cm superiores cuando la especie lo permita, usa trampas cromáticas amarillas para vigilar los adultos y pon en cuarentena las plantas nuevas, que son el origen habitual de una infestación.']},
      {heading: 'Cuándo elegir otro sustrato', paragraphs: ['Un sustrato universal de interior es una buena opción por defecto para las plantas de follaje comunes, pero no una respuesta universal.'], bullets: ['Suculentas, cactus, aloe y lengua de suegra: mézclalo con un 40–60 % de pumita, perlita o grava', 'Orquídeas epífitas: usa en su lugar un medio para orquídeas a base de corteza o musgo', 'Aráceas grandes en macetas grandes: añade corteza y perlita para mantener abierta la zona radicular', 'Esquejes sin raíces: usa un medio pobre en nutrientes, como perlita húmeda o un sustrato de semillero', 'Plantas que ya abonas con un programa líquido estricto: un sustrato sin abono te da el control total']},
    ],
  },
  'propagating-pothos': {
    title: 'Cómo multiplicar el poto por esquejes de nudo en agua o sustrato',
    description: 'Multiplicación del poto paso a paso: elegir los nudos, longitud del esqueje, agua o sustrato, 20–25 °C para enraizar en 2–4 semanas y trasplante con 2–5 cm de raíz.',
    takeaway: 'Todo esqueje de poto necesita al menos un nudo sano; mantenlo a 20–25 °C con luz indirecta brillante y trasplántalo cuando las raíces alcancen 2–5 cm.',
    sections: [
      {heading: 'Localiza el nudo y haz el corte', paragraphs: ['El poto (Epipremnum aureum) enraíza desde sus nudos: los puntos ligeramente engrosados donde cada hoja se une a la guía, normalmente marcados por un pequeño bulto marrón que es una raíz aérea latente. Una hoja con solo su pecíolo a veces enraíza, pero casi nunca produce una guía nueva, porque no tiene yema.', 'Usa una cuchilla limpia y afilada y toma esquejes de 10–15 cm con 2–4 nudos, o corta la guía en trozos de un solo nudo si quieres muchas plantas. Corta aproximadamente 1 cm por debajo de un nudo y quita cualquier hoja que fuera a quedar bajo el agua o bajo la superficie. Elige guías firmes y verdes de una planta sin plagas, no las puntas finas y pálidas de una guía que ha colgado con poca luz. La savia contiene cristales de oxalato cálcico y la ASPCA clasifica el poto como tóxico para perros y gatos, así que recoge los restos y lávate las manos después.']},
      {heading: 'Agua o sustrato: elige uno y mantenlo', paragraphs: ['Los dos métodos funcionan. Lo que perjudica a los esquejes es cambiar de uno a otro, porque las raíces formadas en agua son estructuralmente distintas de las formadas en un medio sólido y deben adaptarse de nuevo al trasladarlas.'], bullets: ['Agua: frasco de cristal, nudos sumergidos y hojas fuera; cambia el agua cada semana para mantenerla oxigenada', 'Agua: las raíces son fáciles de vigilar, pero cuenta con una breve pausa de crecimiento tras pasarlo a maceta', 'Sustrato: perlita húmeda, musgo esfagno o una mezcla 50:50 de perlita y sustrato, con los nudos enterrados 1–2 cm', 'Sustrato: cúbrelo holgadamente con una bolsa transparente o una tapa de bandeja para mantener alta la humedad, ventilando a diario', 'Sustrato: las raíces salen ya adaptadas, así que el paso a maceta es más suave']},
      {heading: 'Condiciones que aceleran el enraizamiento', paragraphs: ['El calor impulsa la formación de raíces. A 20–25 °C las primeras raíces suelen aparecer en 2–4 semanas; por debajo de unos 18 °C el proceso se ralentiza mucho, así que un sitio junto a una salida de calefacción es peor que una estantería cálida sin corrientes. Una manta térmica ajustada a unos 24 °C ayuda en invierno.', 'Dale luz indirecta brillante, unos 5.000–15.000 lux, sin sol directo de mediodía, que recalienta un frasco de agua. No abones: el esqueje no tiene raíces para absorber nutrientes, y las sales solo estresan la superficie de corte. Las hormonas de enraizamiento son opcionales en el poto, que enraíza fácilmente sin ellas. Los cultivares muy variegados como ‘Marble Queen’ tienen menos clorofila y enraízan más despacio que el ‘Jade’ verde.']},
      {heading: 'Trasplante cuando las raíces midan 2–5 cm', paragraphs: ['Pasa a maceta los esquejes enraizados en agua cuando las raíces midan 2–5 cm; esperar a que formen una maraña larga dificulta la transición. Usa una maceta de 8–10 cm con drenaje y una mezcla ligera y bien aireada, y planta de tres a cinco esquejes juntos si quieres una planta frondosa rápidamente.', 'Coloca los nudos 1–2 cm por debajo de la superficie y presiona suavemente. Durante las primeras 1–2 semanas mantén el sustrato uniformemente húmedo para que las raíces formadas en agua no se deshidraten, y pasa después a la rutina normal del poto: regar cuando los 2–5 cm superiores estén secos. Espera unas 6 semanas antes del primer abonado a media dosis.']},
      {heading: 'Qué hacer si un esqueje se estanca', paragraphs: ['Un tallo blando, oscuro o maloliente indica podredumbre: corta hasta llegar a tejido firme y verde por encima del daño, enjuaga el frasco y empieza de nuevo. Que amarillee una hoja durante el enraizamiento es normal, porque el esqueje recicla sus nutrientes. Si no ha enraizado nada tras 6 semanas, las causas habituales son el frío, la poca luz o un nudo dañado o ausente. El agua turbia indica bacterias; cámbiala más a menudo y usa un frasco más pequeño.']},
    ],
  },
  'cleaning-houseplant-leaves': {
    title: 'Cómo limpiar las hojas de las plantas de interior sin dañarlas',
    description: 'Por qué el polvo resta luz a las hojas, cómo limpiar hojas lisas, pilosas y cerosas, y por qué los abrillantadores, la mayonesa y la leche hacen más mal que bien.',
    takeaway: 'Quita el polvo cada 4–6 semanas con agua templada sin más y un paño suave o un pincel adecuado a la hoja, y aprovecha cada limpieza para una inspección minuciosa de plagas.',
    sections: [
      {heading: 'Por qué el polvo le cuesta luz a tu planta', paragraphs: ['Las plantas de interior ya viven con una pequeña fracción de la luz exterior: una habitación típica lejos de las ventanas está a 50–500 lux, frente a unos 100.000 lux a pleno sol de verano. Una película de polvo en el haz de la hoja absorbe y dispersa parte de esa luz antes de que llegue a los cloroplastos del interior, de modo que una planta polvorienta en un lugar de luz media se comporta como si la hubieras alejado de la ventana.', 'El polvo también se acumula en los recovecos donde se refugian la araña roja y los trips, y una película grasienta de cocina retiene aún más. Quitarlo es una de las pocas mejoras de luz que puedes hacer sin mover la planta.']},
      {heading: 'Hojas lisas y anchas: paño húmedo y una mano de apoyo', paragraphs: ['El ficus elástica (Ficus elastica), la Monstera deliciosa, el espatifilo, la ZZ y el ficus lira (Ficus lyrata) tienen cutículas lisas y resistentes que toleran el paño. Usa un paño de microfibra suave humedecido con agua templada, sujeta la hoja por debajo con la otra mano y pasa el paño desde el pecíolo hacia la punta en una sola dirección. Limpia también el envés, donde están la mayoría de los estomas y donde se esconden las plagas.', 'Enjuaga el paño a menudo para no ir extendiendo el polvo. Para una película pegajosa o grasienta, añade una o dos gotas de jabón líquido suave a un litro de agua y vuelve a pasar después con agua sola. Usa guantes con los ficus si eres sensible a su látex, y evita limpiar las hojas jóvenes que aún se están abriendo, que se magullan con facilidad.']},
      {heading: 'Las hojas pilosas, texturizadas y cerosas piden otro enfoque', paragraphs: ['Las hojas aterciopeladas de las violetas africanas (Saintpaulia) y de los filodendros de hoja aterciopelada retienen el agua y se magullan con un paño. Usa en su lugar un pincel suave y seco o una brocha de maquillaje limpia. Mantén el agua fría lejos de las violetas africanas, porque les provoca manchas anulares claras.', 'Muchas suculentas, como la Echeveria, tienen una pruina cerosa y polvorienta (cera epicuticular) que refleja el exceso de sol y no vuelve a formarse una vez frotada. Quita el polvo con una pera de aire o un pincel muy ligero. Las plantas de hoja pequeña, como los helechos, el Ficus benjamina y el rosario (Senecio rowleyanus), se enjuagan mejor bajo una ducha templada y suave con la maceta envuelta en una bolsa de plástico, dejándolas escurrir después fuera del sol directo.']},
      {heading: 'Por qué los abrillantadores, la mayonesa y la leche hacen más mal que bien', paragraphs: ['El brillo natural de una hoja procede de su cutícula cerosa. Los aceites, la mayonesa, la leche y los abrillantadores foliares comerciales recubren esa superficie con una película que puede obstruir los estomas, retener más polvo y, en el caso de los alimentos, enranciarse o criar moho. Algunos abrillantadores en spray además queman el follaje tierno con luz intensa. Ninguno de ellos alimenta a la planta.', 'Si quieres que una planta luzca lo mejor posible, dale luz suficiente y límpiala con agua. Una hoja sana y sin polvo ya tiene todo el brillo que su especie debe tener.']},
      {heading: 'Convierte cada limpieza en una inspección', paragraphs: ['Al limpiar estás más cerca de cada hoja que nunca al regar. Una lupa de 10× hace visibles las primeras señales de problemas semanas antes de que se noten desde el otro lado de la habitación.'], bullets: ['Punteado fino amarillo o blanco en el haz, o telaraña fina: araña roja', 'Mechones blancos algodonosos en las axilas y a lo largo de los nervios: cochinilla algodonosa', 'Bultos marrones o tostados inmóviles en tallos y nervios centrales: cochinillas de escudo', 'Rayas plateadas con motas negras: trips', 'Residuo pegajoso (melaza) en las hojas o en los muebles de debajo: insectos chupadores más arriba', 'Si encuentras plagas, usa un paño limpio para cada planta y aísla la afectada']},
    ],
  },
};

export default articles;
